17	/// ## What it does
18	/// Checks for `if` statements (without `elif` or `else` branches) where the
19	/// body contains only `pass` or `...`
20	///
21	/// ## Why is this bad?
22	/// An `if` statement with an empty body either does nothing (when the
23	/// condition is side-effect-free) or could be replaced with just the
24	/// condition expression (when it has side effects). This pattern commonly
25	/// arises when auto-fixers remove unused imports from conditional blocks
26	/// (e.g., version-dependent imports), leaving behind an empty skeleton.
27	///
28	/// ## Example
29	/// ```python
30	/// import sys
31	///
32	/// if sys.version_info >= (3, 11):
33	///     pass
34	/// ```
35	///
36	/// Use instead:
37	/// ```python
38	/// import sys
39	/// ```
40	///
41	/// ## Fix safety
42	/// When the condition is side-effect-free, the fix removes the entire `if`
43	/// statement.
44	///
45	/// When the condition has side effects (e.g., a function call), the fix
46	/// replaces the `if` statement with just the condition as an expression
47	/// statement, preserving the side effects.
48	///
49	/// Note: conditions consisting solely of a name expression (like
50	/// `if x: pass`) are treated as side-effect-free, even though `if x`
51	/// implicitly calls `x.__bool__()` (or `x.__len__()`), which could have
52	/// side effects if overridden. In practice this is very rare, but if you
53	/// rely on this behavior, suppress the diagnostic with `# noqa: RUF050`.
54	///
55	/// ## Related rules
56	/// - [`needless-else (RUF047)`]: Detects empty `else` clauses. For `if`/`else`
57	///   statements where all branches are empty, `RUF047` first removes the empty
58	///   `else`, and then this rule catches the remaining empty `if`.
59	/// - [`empty-type-checking-block (TC005)`]: Detects empty `if TYPE_CHECKING`
60	///   blocks specifically.
61	#[derive(ViolationMetadata)]
62	#[violation_metadata(preview_since = "0.15.8")]
63	pub(crate) struct UnnecessaryIf;
64	
65	impl AlwaysFixableViolation for UnnecessaryIf {
66	    #[derive_message_formats]
67	    fn message(&self) -> String {
68	        "Empty `if` statement".to_string()
69	    }
70	
71	    fn fix_title(&self) -> String {
72	        "Remove the `if` statement".to_string()
73	    }
74	}
75	
76	/// RUF050
77	pub(crate) fn unnecessary_if(checker: &Checker, stmt: &StmtIf) {
78	    let StmtIf {
79	        test,
80	        body,
81	        elif_else_clauses,
82	        ..
83	    } = stmt;
84	
85	    // Only handle bare `if` blocks — `elif`/`else` branches are handled by
86	    // RUF047 (needless-else)
87	    if !elif_else_clauses.is_empty() {
88	        return;
89	    }
90	
91	    if !is_stub_body(body) {
92	        return;
93	    }
94	
95	    // Skip `if TYPE_CHECKING` blocks — handled by TC005
96	    if typing::is_type_checking_block(stmt, checker.semantic()) {
97	        return;
98	    }
99	
100	    // Skip if the body contains a comment
101	    if if_contains_comments(stmt, checker) {
102	        return;
103	    }
104	
105	    let has_side_effects = contains_effect(test, |id| checker.semantic().has_builtin_binding(id))
106	        || any_over_expr(test, &|expr| matches!(expr, Expr::Named(_)));
107	
108	    let mut diagnostic = checker.report_diagnostic(UnnecessaryIf, stmt.range());
109	
110	    if has_side_effects {
111	        // Replace `if cond: pass` with `cond` as an expression statement.
112	        // Walrus operators need parentheses to be valid as statements.
113	        let condition_text = checker.locator().slice(test.range());
114	        let replacement = if test.is_named_expr() {
115	            format!("({condition_text})")
116	        } else {
117	            condition_text.to_string()
118	        };
119	        let edit = Edit::range_replacement(replacement, stmt.range());
120	        diagnostic.set_fix(Fix::safe_edit(edit));
121	    } else {
122	        let stmt_ref = checker.semantic().current_statement();
123	        let parent = checker.semantic().current_statement_parent();
124	        let edit = fix::edits::delete_stmt(stmt_ref, parent, checker.locator(), checker.indexer());
125	        let fix = Fix::safe_edit(edit).isolate(Checker::isolation(
126	            checker.semantic().current_statement_parent_id(),
127	        ));
128	        diagnostic.set_fix(fix);
129	    }
130	}
